    # [doc = " Spawns a new thread, returning a [`JoinHandle`] for it."] # [doc = ""] # [doc = " The join handle provides a [`join`] method that can be used to join the spawned"] # [doc = " thread. If the spawned thread panics, [`join`] will return an [`Err`] containing"] # [doc = " the argument given to [`panic!`]."] # [doc = ""] # [doc = " If the join handle is dropped, the spawned thread will implicitly be *detached*."] # [doc = " In this case, the spawned thread may no longer be joined."] # [doc = " (It is the responsibility of the program to either eventually join threads it"] # [doc = " creates or detach them; otherwise, a resource leak will result.)"] # [doc = ""] # [doc = " This call will create a thread using default parameters of [`Builder`], if you"] # [doc = " want to specify the stack size or the name of the thread, use this API"] # [doc = " instead."] # [doc = ""] # [doc = " As you can see in the signature of `spawn` there are two constraints on"] # [doc = " both the closure given to `spawn` and its return value, let's explain them:"] # [doc = ""] # [doc = " - The `'static` constraint means that the closure and its return value"] # [doc = "   must have a lifetime of the whole program execution. The reason for this"] # [doc = "   is that threads can outlive the lifetime they have been created in."] # [doc = ""] # [doc = "   Indeed if the thread, and by extension its return value, can outlive their"] # [doc = "   caller, we need to make sure that they will be valid afterwards, and since"] # [doc = "   we *can't* know when it will return we need to have them valid as long as"] # [doc = "   possible, that is until the end of the program, hence the `'static`"] # [doc = "   lifetime."] # [doc = " - The [`Send`] constraint is because the closure will need to be passed"] # [doc = "   *by value* from the thread where it is spawned to the new thread. Its"] # [doc = "   return value will need to be passed from the new thread to the thread"] # [doc = "   where it is `join`ed."] # [doc = "   As a reminder, the [`Send`] marker trait expresses that it is safe to be"] # [doc = "   passed from thread to thread. [`Sync`] expresses that it is safe to have a"] # [doc = "   reference be passed from thread to thread."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the OS fails to create a thread; use [`Builder::spawn`]"] # [doc = " to recover from such errors."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Creating a thread."] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let handler = thread::spawn(|| {"] # [doc = "     // thread code"] # [doc = " });"] # [doc = ""] # [doc = " handler.join().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " As mentioned in the module documentation, threads are usually made to"] # [doc = " communicate using [`channels`], here is how it usually looks."] # [doc = ""] # [doc = " This example also shows how to use `move`, in order to give ownership"] # [doc = " of values to a thread."] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = " use std::sync::mpsc::channel;"] # [doc = ""] # [doc = " let (tx, rx) = channel();"] # [doc = ""] # [doc = " let sender = thread::spawn(move || {"] # [doc = "     tx.send(\"Hello, thread\".to_owned())"] # [doc = "         .expect(\"Unable to send on channel\");"] # [doc = " });"] # [doc = ""] # [doc = " let receiver = thread::spawn(move || {"] # [doc = "     let value = rx.recv().expect(\"Unable to receive from channel\");"] # [doc = "     println!(\"{value}\");"] # [doc = " });"] # [doc = ""] # [doc = " sender.join().expect(\"The sender thread has panicked\");"] # [doc = " receiver.join().expect(\"The receiver thread has panicked\");"] # [doc = " ```"] # [doc = ""] # [doc = " A thread can also return a value through its [`JoinHandle`], you can use"] # [doc = " this to make asynchronous computations (futures might be more appropriate"] # [doc = " though)."] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let computation = thread::spawn(|| {"] # [doc = "     // Some expensive computation."] # [doc = "     42"] # [doc = " });"] # [doc = ""] # [doc = " let result = computation.join().unwrap();"] # [doc = " println!(\"{result}\");"] # [doc = " ```"] # [doc = ""] # [doc = " # Notes"] # [doc = ""] # [doc = " This function has the same minimal guarantee regarding \"foreign\" unwinding operations (e.g."] # [doc = " an exception thrown from C++ code, or a `panic!` in Rust code compiled or linked with a"] # [doc = " different runtime) as [`catch_unwind`]; namely, if the thread created with `thread::spawn`"] # [doc = " unwinds all the way to the root with such an exception, one of two behaviors are possible,"] # [doc = " and it is unspecified which will occur:"] # [doc = ""] # [doc = " * The process aborts."] # [doc = " * The process does not abort, and [`join`] will return a `Result::Err`"] # [doc = "   containing an opaque type."] # [doc = ""] # [doc = " [`catch_unwind`]: ../../std/panic/fn.catch_unwind.html"] # [doc = " [`channels`]: crate::sync::mpsc"] # [doc = " [`join`]: JoinHandle::join"] # [doc = " [`Err`]: crate::result::Result::Err"] # [stable (feature = "rust1" , since = "1.0.0")] # [cfg_attr (miri , track_caller)] pub fn spawn < F , T > (f : F) -> JoinHandle < T > where F : FnOnce () -> T , F : Send + 'static , T : Send + 'static , { Builder :: new () . spawn (f) . expect ("failed to spawn thread") }
