mkfn!{
    park_introspect!();
    # [doc = " Blocks unless or until the current thread's token is made available."] # [doc = ""] # [doc = " A call to `park` does not guarantee that the thread will remain parked"] # [doc = " forever, and callers should be prepared for this possibility. However,"] # [doc = " it is guaranteed that this function will not panic (it may abort the"] # [doc = " process if the implementation encounters some rare errors)."] # [doc = ""] # [doc = " # `park` and `unpark`"] # [doc = ""] # [doc = " Every thread is equipped with some basic low-level blocking support, via the"] # [doc = " [`thread::park`][`park`] function and [`thread::Thread::unpark`][`unpark`]"] # [doc = " method. [`park`] blocks the current thread, which can then be resumed from"] # [doc = " another thread by calling the [`unpark`] method on the blocked thread's"] # [doc = " handle."] # [doc = ""] # [doc = " Conceptually, each [`Thread`] handle has an associated token, which is"] # [doc = " initially not present:"] # [doc = ""] # [doc = " * The [`thread::park`][`park`] function blocks the current thread unless or"] # [doc = "   until the token is available for its thread handle, at which point it"] # [doc = "   atomically consumes the token. It may also return *spuriously*, without"] # [doc = "   consuming the token. [`thread::park_timeout`] does the same, but allows"] # [doc = "   specifying a maximum time to block the thread for."] # [doc = ""] # [doc = " * The [`unpark`] method on a [`Thread`] atomically makes the token available"] # [doc = "   if it wasn't already. Because the token can be held by a thread even if it is currently not"] # [doc = "   parked, [`unpark`] followed by [`park`] will result in the second call returning immediately."] # [doc = "   However, note that to rely on this guarantee, you need to make sure that your `unpark` happens"] # [doc = "   after all `park` that may be done by other data structures!"] # [doc = ""] # [doc = " The API is typically used by acquiring a handle to the current thread, placing that handle in a"] # [doc = " shared data structure so that other threads can find it, and then `park`ing in a loop. When some"] # [doc = " desired condition is met, another thread calls [`unpark`] on the handle. The last bullet point"] # [doc = " above guarantees that even if the `unpark` occurs before the thread is finished `park`ing, it"] # [doc = " will be woken up properly."] # [doc = ""] # [doc = " Note that the coordination via the shared data structure is crucial: If you `unpark` a thread"] # [doc = " without first establishing that it is about to be `park`ing within your code, that `unpark` may"] # [doc = " get consumed by a *different* `park` in the same thread, leading to a deadlock. This also means"] # [doc = " you must not call unknown code between setting up for parking and calling `park`; for instance,"] # [doc = " if you invoke `println!`, that may itself call `park` and thus consume your `unpark` and cause a"] # [doc = " deadlock."] # [doc = ""] # [doc = " The motivation for this design is twofold:"] # [doc = ""] # [doc = " * It avoids the need to allocate mutexes and condvars when building new"] # [doc = "   synchronization primitives; the threads already provide basic"] # [doc = "   blocking/signaling."] # [doc = ""] # [doc = " * It can be implemented very efficiently on many platforms."] # [doc = ""] # [doc = " # Memory Ordering"] # [doc = ""] # [doc = " Calls to `unpark` _synchronize-with_ calls to `park`, meaning that memory"] # [doc = " operations performed before a call to `unpark` are made visible to the thread that"] # [doc = " consumes the token and returns from `park`. Note that all `park` and `unpark`"] # [doc = " operations for a given thread form a total order and _all_ prior `unpark` operations"] # [doc = " synchronize-with `park`."] # [doc = ""] # [doc = " In atomic ordering terms, `unpark` performs a `Release` operation and `park`"] # [doc = " performs the corresponding `Acquire` operation. Calls to `unpark` for the same"] # [doc = " thread form a [release sequence]."] # [doc = ""] # [doc = " Note that being unblocked does not imply a call was made to `unpark`, because"] # [doc = " wakeups can also be spurious. For example, a valid, but inefficient,"] # [doc = " implementation could have `park` and `unpark` return immediately without doing anything,"] # [doc = " making *all* wakeups spurious."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = " use std::sync::atomic::{Ordering, AtomicBool};"] # [doc = " use std::time::Duration;"] # [doc = ""] # [doc = " static QUEUED: AtomicBool = AtomicBool::new(false);"] # [doc = " static FLAG: AtomicBool = AtomicBool::new(false);"] # [doc = ""] # [doc = " let parked_thread = thread::spawn(move || {"] # [doc = "     println!(\"Thread spawned\");"] # [doc = "     // Signal that we are going to `park`. Between this store and our `park`, there may"] # [doc = "     // be no other `park`, or else that `park` could consume our `unpark` token!"] # [doc = "     QUEUED.store(true, Ordering::Release);"] # [doc = "     // We want to wait until the flag is set. We *could* just spin, but using"] # [doc = "     // park/unpark is more efficient."] # [doc = "     while !FLAG.load(Ordering::Acquire) {"] # [doc = "         // We can *not* use `println!` here since that could use thread parking internally."] # [doc = "         thread::park();"] # [doc = "         // We *could* get here spuriously, i.e., way before the 10ms below are over!"] # [doc = "         // But that is no problem, we are in a loop until the flag is set anyway."] # [doc = "     }"] # [doc = "     println!(\"Flag received\");"] # [doc = " });"] # [doc = ""] # [doc = " // Let some time pass for the thread to be spawned."] # [doc = " thread::sleep(Duration::from_millis(10));"] # [doc = ""] # [doc = " // Ensure the thread is about to park."] # [doc = " // This is crucial! It guarantees that the `unpark` below is not consumed"] # [doc = " // by some other code in the parked thread (e.g. inside `println!`)."] # [doc = " while !QUEUED.load(Ordering::Acquire) {"] # [doc = "     // Spinning is of course inefficient; in practice, this would more likely be"] # [doc = "     // a dequeue where we have no work to do if there's nobody queued."] # [doc = "     std::hint::spin_loop();"] # [doc = " }"] # [doc = ""] # [doc = " // Set the flag, and let the thread wake up."] # [doc = " // There is no race condition here: if `unpark`"] # [doc = " // happens first, `park` will return immediately."] # [doc = " // There is also no other `park` that could consume this token,"] # [doc = " // since we waited until the other thread got queued."] # [doc = " // Hence there is no risk of a deadlock."] # [doc = " FLAG.store(true, Ordering::Release);"] # [doc = " println!(\"Unpark the thread\");"] # [doc = " parked_thread.thread().unpark();"] # [doc = ""] # [doc = " parked_thread.join().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " [`unpark`]: Thread::unpark"] # [doc = " [`thread::park_timeout`]: park_timeout"] # [doc = " [release sequence]: https://en.cppreference.com/w/cpp/atomic/memory_order#Release_sequence"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn park () { let guard = PanicGuard ; unsafe { current () . park () ; } forget (guard) ; }
}

