mkitem!{mkimpl!{impl Thread { pub (crate) fn new (id : ThreadId , name : Option < String >) -> Thread { let name = name . map (ThreadNameString :: from) ; let inner = unsafe { let mut arc = Arc :: < Inner > :: new_uninit () ; let ptr = Arc :: get_mut_unchecked (& mut arc) . as_mut_ptr () ; (& raw mut (* ptr) . name) . write (name) ; (& raw mut (* ptr) . id) . write (id) ; Parker :: new_in_place (& raw mut (* ptr) . parker) ; Pin :: new_unchecked (arc . assume_init ()) } ; Thread { inner } } # [doc = " Like the public [`park`], but callable on any handle. This is used to"] # [doc = " allow parking in TLS destructors."] # [doc = ""] # [doc = " # Safety"] # [doc = " May only be called from the thread to which this handle belongs."] pub (crate) unsafe fn park (& self) { unsafe { self . inner . as_ref () . parker () . park () } } # [doc = " Like the public [`park_timeout`], but callable on any handle. This is"] # [doc = " used to allow parking in TLS destructors."] # [doc = ""] # [doc = " # Safety"] # [doc = " May only be called from the thread to which this handle belongs."] pub (crate) unsafe fn park_timeout (& self , dur : Duration) { unsafe { self . inner . as_ref () . parker () . park_timeout (dur) } } # [doc = " Atomically makes the handle's token available if it is not already."] # [doc = ""] # [doc = " Every thread is equipped with some basic low-level blocking support, via"] # [doc = " the [`park`][park] function and the `unpark()` method. These can be"] # [doc = " used as a more CPU-efficient implementation of a spinlock."] # [doc = ""] # [doc = " See the [park documentation][park] for more details."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = " use std::time::Duration;"] # [doc = " use std::sync::atomic::{AtomicBool, Ordering};"] # [doc = ""] # [doc = " static QUEUED: AtomicBool = AtomicBool::new(false);"] # [doc = ""] # [doc = " let parked_thread = thread::Builder::new()"] # [doc = "     .spawn(|| {"] # [doc = "         println!(\"Parking thread\");"] # [doc = "         QUEUED.store(true, Ordering::Release);"] # [doc = "         thread::park();"] # [doc = "         println!(\"Thread unparked\");"] # [doc = "     })"] # [doc = "     .unwrap();"] # [doc = ""] # [doc = " // Let some time pass for the thread to be spawned."] # [doc = " thread::sleep(Duration::from_millis(10));"] # [doc = ""] # [doc = " // Wait until the other thread is queued."] # [doc = " // This is crucial! It guarantees that the `unpark` below is not consumed"] # [doc = " // by some other code in the parked thread (e.g. inside `println!`)."] # [doc = " while !QUEUED.load(Ordering::Acquire) {"] # [doc = "     // Spinning is of course inefficient; in practice, this would more likely be"] # [doc = "     // a dequeue where we have no work to do if there's nobody queued."] # [doc = "     std::hint::spin_loop();"] # [doc = " }"] # [doc = ""] # [doc = " println!(\"Unpark the thread\");"] # [doc = " parked_thread.thread().unpark();"] # [doc = ""] # [doc = " parked_thread.join().unwrap();"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [inline] pub fn unpark (& self) { self . inner . as_ref () . parker () . unpark () ; } # [doc = " Gets the thread's unique identifier."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let other_thread = thread::spawn(|| {"] # [doc = "     thread::current().id()"] # [doc = " });"] # [doc = ""] # [doc = " let other_thread_id = other_thread.join().unwrap();"] # [doc = " assert!(thread::current().id() != other_thread_id);"] # [doc = " ```"] # [stable (feature = "thread_id" , since = "1.19.0")] # [must_use] pub fn id (& self) -> ThreadId { self . inner . id } # [doc = " Gets the thread's name."] # [doc = ""] # [doc = " For more information about named threads, see"] # [doc = " [this module-level documentation][naming-threads]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Threads by default have no name specified:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let builder = thread::Builder::new();"] # [doc = ""] # [doc = " let handler = builder.spawn(|| {"] # [doc = "     assert!(thread::current().name().is_none());"] # [doc = " }).unwrap();"] # [doc = ""] # [doc = " handler.join().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " Thread with a specified name:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let builder = thread::Builder::new()"] # [doc = "     .name(\"foo\".into());"] # [doc = ""] # [doc = " let handler = builder.spawn(|| {"] # [doc = "     assert_eq!(thread::current().name(), Some(\"foo\"))"] # [doc = " }).unwrap();"] # [doc = ""] # [doc = " handler.join().unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " [naming-threads]: ./index.html#naming-threads"] # [stable (feature = "rust1" , since = "1.0.0")] # [must_use] pub fn name (& self) -> Option < & str > { if let Some (name) = & self . inner . name { Some (name . as_str ()) } else if main_thread :: get () == Some (self . inner . id) { Some ("main") } else { None } } # [doc = " Consumes the `Thread`, returning a raw pointer."] # [doc = ""] # [doc = " To avoid a memory leak the pointer must be converted"] # [doc = " back into a `Thread` using [`Thread::from_raw`]. The pointer is"] # [doc = " guaranteed to be aligned to at least 8 bytes."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(thread_raw)]"] # [doc = ""] # [doc = " use std::thread::{self, Thread};"] # [doc = ""] # [doc = " let thread = thread::current();"] # [doc = " let id = thread.id();"] # [doc = " let ptr = Thread::into_raw(thread);"] # [doc = " unsafe {"] # [doc = "     assert_eq!(Thread::from_raw(ptr).id(), id);"] # [doc = " }"] # [doc = " ```"] # [unstable (feature = "thread_raw" , issue = "97523")] pub fn into_raw (self) -> * const () { let inner = unsafe { Pin :: into_inner_unchecked (self . inner) } ; Arc :: into_raw (inner) as * const () } # [doc = " Constructs a `Thread` from a raw pointer."] # [doc = ""] # [doc = " The raw pointer must have been previously returned"] # [doc = " by a call to [`Thread::into_raw`]."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This function is unsafe because improper use may lead"] # [doc = " to memory unsafety, even if the returned `Thread` is never"] # [doc = " accessed."] # [doc = ""] # [doc = " Creating a `Thread` from a pointer other than one returned"] # [doc = " from [`Thread::into_raw`] is **undefined behavior**."] # [doc = ""] # [doc = " Calling this function twice on the same raw pointer can lead"] # [doc = " to a double-free if both `Thread` instances are dropped."] # [unstable (feature = "thread_raw" , issue = "97523")] pub unsafe fn from_raw (ptr : * const ()) -> Thread { unsafe { Thread { inner : Pin :: new_unchecked (Arc :: from_raw (ptr as * const Inner)) } } } fn cname (& self) -> Option < & CStr > { if let Some (name) = & self . inner . name { Some (name . as_cstr ()) } else if main_thread :: get () == Some (self . inner . id) { Some (c"main") } else { None } } }}}
