    # [doc = " Returns an estimate of the default amount of parallelism a program should use."] # [doc = ""] # [doc = " Parallelism is a resource. A given machine provides a certain capacity for"] # [doc = " parallelism, i.e., a bound on the number of computations it can perform"] # [doc = " simultaneously. This number often corresponds to the amount of CPUs a"] # [doc = " computer has, but it may diverge in various cases."] # [doc = ""] # [doc = " Host environments such as VMs or container orchestrators may want to"] # [doc = " restrict the amount of parallelism made available to programs in them. This"] # [doc = " is often done to limit the potential impact of (unintentionally)"] # [doc = " resource-intensive programs on other programs running on the same machine."] # [doc = ""] # [doc = " # Limitations"] # [doc = ""] # [doc = " The purpose of this API is to provide an easy and portable way to query"] # [doc = " the default amount of parallelism the program should use. Among other things it"] # [doc = " does not expose information on NUMA regions, does not account for"] # [doc = " differences in (co)processor capabilities or current system load,"] # [doc = " and will not modify the program's global state in order to more accurately"] # [doc = " query the amount of available parallelism."] # [doc = ""] # [doc = " Where both fixed steady-state and burst limits are available the steady-state"] # [doc = " capacity will be used to ensure more predictable latencies."] # [doc = ""] # [doc = " Resource limits can be changed during the runtime of a program, therefore the value is"] # [doc = " not cached and instead recomputed every time this function is called. It should not be"] # [doc = " called from hot code."] # [doc = ""] # [doc = " The value returned by this function should be considered a simplified"] # [doc = " approximation of the actual amount of parallelism available at any given"] # [doc = " time. To get a more detailed or precise overview of the amount of"] # [doc = " parallelism available to the program, you may wish to use"] # [doc = " platform-specific APIs as well. The following platform limitations currently"] # [doc = " apply to `available_parallelism`:"] # [doc = ""] # [doc = " On Windows:"] # [doc = " - It may undercount the amount of parallelism available on systems with more"] # [doc = "   than 64 logical CPUs. However, programs typically need specific support to"] # [doc = "   take advantage of more than 64 logical CPUs, and in the absence of such"] # [doc = "   support, the number returned by this function accurately reflects the"] # [doc = "   number of logical CPUs the program can use by default."] # [doc = " - It may overcount the amount of parallelism available on systems limited by"] # [doc = "   process-wide affinity masks, or job object limitations."] # [doc = ""] # [doc = " On Linux:"] # [doc = " - It may overcount the amount of parallelism available when limited by a"] # [doc = "   process-wide affinity mask or cgroup quotas and `sched_getaffinity()` or cgroup fs can't be"] # [doc = "   queried, e.g. due to sandboxing."] # [doc = " - It may undercount the amount of parallelism if the current thread's affinity mask"] # [doc = "   does not reflect the process' cpuset, e.g. due to pinned threads."] # [doc = " - If the process is in a cgroup v1 cpu controller, this may need to"] # [doc = "   scan mountpoints to find the corresponding cgroup v1 controller,"] # [doc = "   which may take time on systems with large numbers of mountpoints."] # [doc = "   (This does not apply to cgroup v2, or to processes not in a"] # [doc = "   cgroup.)"] # [doc = " - It does not attempt to take `ulimit` into account. If there is a limit set on the number of"] # [doc = "   threads, `available_parallelism` cannot know how much of that limit a Rust program should"] # [doc = "   take, or know in a reliable and race-free way how much of that limit is already taken."] # [doc = ""] # [doc = " On all targets:"] # [doc = " - It may overcount the amount of parallelism available when running in a VM"] # [doc = " with CPU usage limits (e.g. an overcommitted host)."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This function will, but is not limited to, return errors in the following"] # [doc = " cases:"] # [doc = ""] # [doc = " - If the amount of parallelism is not known for the target platform."] # [doc = " - If the program lacks permission to query the amount of parallelism made"] # [doc = "   available to it."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # #![allow(dead_code)]"] # [doc = " use std::{io, thread};"] # [doc = ""] # [doc = " fn main() -> io::Result<()> {"] # [doc = "     let count = thread::available_parallelism()?.get();"] # [doc = "     assert!(count >= 1_usize);"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] # [doc (alias = "available_concurrency")] # [doc (alias = "hardware_concurrency")] # [doc (alias = "num_cpus")] # [stable (feature = "available_parallelism" , since = "1.59.0")] pub fn available_parallelism () -> io :: Result < NonZero < usize > > { imp :: available_parallelism () }
